SELECT analytics_order_facts.month, SUM(analytics_order_facts.gross_revenue) AS gross_revenue FROM analytics_order_facts WHERE analytics_order_facts.year IN (2022, 2023) AND analytics_order_facts.region = 'North' AND analytics_order_facts.channel = 'online' AND analytics_order_facts.customer_segment = 'consumer' GROUP BY analytics_order_facts.month ORDER BY analytics_order_facts.month ASC LIMIT 24
